-- The paperclip bucket (ops ZHC-1B).
--
-- MoltyCel/paperclip-moltrust registers every agent a Paperclip company hires
-- and sends platform=paperclip. Without an arm here those registrations were
-- displayed as `other`; they now get their own bucket next to the other
-- framework integrations. The registry export counts the same platform in
-- `usage` (app/sql/registry_export.sql).
--
-- Generated by app.funnel.build_bucket_function_sql(); tests/test_funnel.py
-- asserts this file still matches it. Applied by hand with psql, like the two
-- migrations before it; deploy.yml does not run migrations.

CREATE OR REPLACE FUNCTION funnel_platform_bucket(p text)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
    SELECT CASE lower(trim(coalesce(p, '')))
        WHEN 'ownify' THEN 'partner'
        WHEN 'clawhub' THEN 'clawhub'
        WHEN 'hermes' THEN 'hermes'
        WHEN 'smithery' THEN 'smithery'
        WHEN 'glama' THEN 'glama'
        WHEN 'a2a' THEN 'a2a'
        WHEN 'erc8004' THEN 'erc8004'
        WHEN 'erc-8004' THEN 'erc8004'
        WHEN 'rnwy' THEN 'rnwy'
        WHEN 'virtuals-acp' THEN 'virtuals-acp'
        WHEN 'virtuals' THEN 'virtuals-acp'
        WHEN 'virtuals_acp' THEN 'virtuals-acp'
        WHEN 'olas' THEN 'olas'
        WHEN 'taskmarket' THEN 'taskmarket'
        WHEN 'x402-bazaar' THEN 'x402-bazaar'
        WHEN 'x402bazaar' THEN 'x402-bazaar'
        WHEN 'bazaar' THEN 'x402-bazaar'
        WHEN 'langchain' THEN 'langchain'
        WHEN 'moltrust-langchain' THEN 'langchain'
        WHEN 'crewai' THEN 'crewai'
        WHEN 'moltrust-crewai' THEN 'crewai'
        WHEN 'openai-agents' THEN 'openai-agents'
        WHEN 'openai_agents' THEN 'openai-agents'
        WHEN 'vercel-ai' THEN 'vercel-ai'
        WHEN 'vercel' THEN 'vercel-ai'
        WHEN 'ai-sdk' THEN 'vercel-ai'
        WHEN 'paperclip' THEN 'paperclip'
        WHEN 'sdk' THEN 'sdk'
        WHEN 'gate' THEN 'gate'
        WHEN 'moltrust-gate' THEN 'gate'
        ELSE 'other'
    END
$$;
